diff --git a/src/upgrades/4.3.0/migrate_restrict_chat.js b/src/upgrades/4.3.0/migrate_restrict_chat.js
new file mode 100644
index 0000000000..e6a1e65998
--- /dev/null
+++ b/src/upgrades/4.3.0/migrate_restrict_chat.js
@@ -0,0 +1,48 @@
+'use strict';
+
+const db = require('../../database');
+const batch = require('../../batch');
+
+module.exports = {
+	name: 'Migrate restrictChat setting to chatAllowList',
+	timestamp: Date.UTC(2025, 3, 10),
+	method: async function () {
+		const { progress } = this;
+
+		await batch.processSortedSet('users:joindate', async (uids) => {
+			const keys = uids.map(uid => `user:${uid}:settings`);
+			const settingsData = await db.getObjectsFields(keys, ['restrictChat', 'chatAllowList']);
+
+			await Promise.all(uids.map(async (uid, idx) => {
+				const settings = settingsData[idx];
+				if (!settings || parseInt(settings.restrictChat, 10) !== 1) {
+					return;
+				}
+
+				let allowList = [];
+				if (settings.chatAllowList) {
+					try {
+						const parsed = JSON.parse(settings.chatAllowList);
+						if (Array.isArray(parsed)) {
+							allowList = parsed;
+						}
+					} catch (e) {
+						allowList = [];
+					}
+				}
+
+				const followingUids = await db.getSortedSetRange(`following:${uid}`, 0, -1);
+				const merged = Array.from(new Set([...allowList, ...followingUids].map(u => parseInt(u, 10))));
+
+				await db.setObject(`user:${uid}:settings`, {
+					chatAllowList: JSON.stringify(merged),
+				});
+			}));
+
+			progress.incr(uids.length);
+		}, {
+			batch: 500,
+			progress,
+		});
+	},
+};
