diff --git a/src/topics/backlinks.js b/src/topics/backlinks.js
new file mode 100644
index 0000000000..03996bf903
--- /dev/null
+++ b/src/topics/backlinks.js
@@ -0,0 +1,51 @@
+'use strict';
+
+const nconf = require('nconf');
+const _ = require('lodash');
+
+const db = require('../database');
+const meta = require('../meta');
+
+module.exports = function (Topics) {
+	Topics.syncBacklinks = async (postData) => {
+		if (!postData) {
+			throw new Error('[[error:invalid-data]]');
+		}
+
+		if (!meta.config.topicBacklinks || !postData.content) {
+			return 0;
+		}
+
+		const { pid, content } = postData;
+		const escapedBaseUrl = nconf.get('url').replace(/[/\\^$*+?.()|[\]{}]/g, '\\$&');
+		const backlinkRegex = new RegExp(`(?:${escapedBaseUrl})?/topic/(\\d+)`, 'g');
+
+		const matches = [...content.matchAll(backlinkRegex)].map(match => parseInt(match[1], 10));
+		let tids = _.uniq(matches).filter(tid => !isNaN(tid) && tid !== parseInt(postData.tid, 10));
+
+		if (tids.length) {
+			const exists = await Topics.exists(tids);
+			tids = tids.filter((tid, idx) => exists[idx]);
+		}
+
+		if (pid) {
+			// Remove any previously-set backlinks for this post, they'll be re-added below if still applicable
+			await db.delete(`pid:${pid}:backlinks`);
+			if (tids.length) {
+				await db.sortedSetAdd(`pid:${pid}:backlinks`, tids.map(() => Date.now()), tids);
+			}
+		}
+
