+UserEmail.getEmailForValidation = async (uid) => {
+	// Attempts to determine the email that should be used for validation purposes for
+	// a given uid. Order of priority:
+	//  1. the user's currently saved email (`user:<uid>` -> `email`)
+	//  2. the email tied to their most recent (still tracked) confirmation code
+	let email = await user.getUserField(uid, 'email');
+	if (!email) {
+		const code = await db.get(`confirm:byUid:${uid}`);
+		const confirmObj = code ? await db.getObject(`confirm:${code}`) : null;
+		if (confirmObj && confirmObj.email && parseInt(uid, 10) === parseInt(confirmObj.uid, 10)) {
+			email = confirmObj.email;
+		}
+	}
+	return email;
+};
+
+UserEmail.isValidationPending = async (uid, email) => {
+	const code = await db.get(`confirm:byUid:${uid}`);
+	if (!code) {
+		return false;
+	}
+	const confirmObj = await db.getObject(`confirm:${code}`);
+	if (!confirmObj) {
