new file mode 100644
index 0000000000..4433e9b762
--- /dev/null
+++ b/src/controllers/well-known.js
@@ -0,0 +1,51 @@
+'use strict';
+
+const nconf = require('nconf');
+
+const user = require('../user');
+const privileges = require('../privileges');
+
+const wellKnownController = module.exports;
+
+wellKnownController.webfinger = async (req, res) => {
+	const { resource } = req.query;
+	if (!resource) {
+		return res.sendStatus(400);
+	}
+
+	const match = /^acct:(.+)@(.+)$/.exec(resource);
+	if (!match) {
+		return res.sendStatus(400);
+	}
+
+	const [, username, hostname] = match;
+	const { hostname: configHostname } = nconf.get('url_parsed');
+	if (hostname !== configHostname) {
+		return res.sendStatus(404);
+	}
+
+	const canView = await privileges.global.can('view:users', req.uid);
+	if (!canView) {
+		return res.sendStatus(403);
+	}
+
+	const uid = await user.getUidByUsername(username);
+	if (!uid) {
+		return res.sendStatus(404);
+	}
+
+	const userslug = await user.getUserField(uid, 'userslug');
+	const profileUrl = `${nconf.get('url')}/user/${userslug}`;
+
+	res.status(200).json({
+		subject: resource,
+		aliases: [profileUrl],
+		links: [
+			{
+				rel: 'http://webfinger.net/rel/profile-page',
+				type: 'text/html',
+				href: profileUrl,
+			},
+		],
+	});
+};
